steps.text:
/*
	VIOC_voices_es.sqf - agregado por tools/vio_build.py (copia configurada, no es del autor de la mision).
	Parche "voices_es": voces de radio en espanol (mod "Spanish Voice-Overs and Radio Protocol", Workshop 2868468383,
	voz MALE01ESPA) para el ejercito de Colombia, la insurgencia, la milicia, los civiles y el jugador.
	Parametro de lobby VIOC_VOICES_ES: 0 = no, 1 = si (si el mod esta cargado), 2 = Auto (por defecto): solo si el mod
	esta cargado Y Colombia juega en algun bando (CTI_COL_SIDE, mision B).
	- setSpeaker y setPitch tienen efecto local: cada maquina con jugador (y el servidor) aplica la voz a todas las
	  unidades que ve, sin trafico de red. Repasa allUnits y los agentes (civiles de civ_people) cada VIOC_ES_EVERY s.
	- Quedan en ingles los soldados de EE. UU. (facciones rhs_faction_us*, CUP_B_US*, CUP_B_USMC*: apoyo de EE. UU.).
	  Sin Colombia en juego (mision A) y con "Si": solo civiles y guerrilla (Resistencia); los ejercitos no cambian.
	- Tono distinto por unidad (setPitch 0.90-1.10): el mod trae una sola voz.
	Consola (LOCAL EXEC): hint (call VIOC_ES_fnc_info);
*/
if (!isNil "VIOC_ES_LOADED") exitWith {};
VIOC_ES_LOADED = true;

VIOC_ES_VOICE = "MALE01ESPA";
VIOC_ES_EVERY = 8;                 // s entre repasos
VIOC_ES_KEEP = ["rhs_faction_us", "cup_b_us", "cup_b_usmc"];   // prefijos de faccion (minusculas) que siguen en ingles
VIOC_ES_DONE = 0;

//--- true si la unidad debe hablar en espanol: civiles, el bando de Colombia y los bandos insurgentes (VIOC_ES_INS),
//--- menos las facciones de EE. UU.
VIOC_ES_fnc_wants = {
	params ["_u"];
	private _s = side group _u;
	if (isNull group _u) then {_s = side _u};   //--- agentes (civiles de civ_people): sin grupo
	if (_s isEqualTo civilian) exitWith {true};
	if !((_s isEqualTo VIOC_ES_COLSIDE) || {_s in VIOC_ES_INS}) exitWith {false};
	private _f = toLower getText (configOf _u >> "faction");
	(VIOC_ES_KEEP findIf {(_f find _x) == 0}) < 0
};

VIOC_ES_fnc_pass = {
	private _n = 0;
	{
		if (alive _x && {isNil {_x getVariable "vioc_es"}}) then {
			_x setVariable ["vioc_es", true];
			if ([_x] call VIOC_ES_fnc_wants) then {
				_x setSpeaker VIOC_ES_VOICE;
				_x setPitch (0.9 + random 0.2);
				_n = _n + 1;
			};
		};
	} forEach (allUnits + ((agents apply {agent _x}) select {_x isKindOf "CAManBase"}));
	VIOC_ES_DONE = VIOC_ES_DONE + _n;
};

VIOC_ES_fnc_info = {
	format ["Voces en espanol: activas %1 (parametro %2, mod %3); bando de Colombia %4; bandos insurgentes en espanol %5; unidades con voz espanola: %6",
		missionNamespace getVariable ["VIOC_ES_ON", false], missionNamespace getVariable ["VIOC_VOICES_ES", 2],
		isClass (configFile >> "CfgVoice" >> VIOC_ES_VOICE), missionNamespace getVariable ["VIOC_ES_COLSIDE", sideUnknown],
		missionNamespace getVariable ["VIOC_ES_INS", []], VIOC_ES_DONE]
};

[] spawn {
	waitUntil {sleep 1; !isNil "CTI_WEST_ID" && {!isNil "CTI_COL_SIDE"}};
	private _p = missionNamespace getVariable ["VIOC_VOICES_ES", 2];
	if !(_p isEqualType 0) then {_p = 2};
	private _mod = isClass (configFile >> "CfgVoice" >> VIOC_ES_VOICE);
	private _col = CTI_COL_SIDE;
	VIOC_ES_COLSIDE = if (_col isEqualTo CTI_WEST_ID) then {west} else {if (_col isEqualTo CTI_EAST_ID) then {east} else {sideUnknown}};
	//--- con Colombia en juego (mision B): la insurgencia y la milicia (los otros dos bandos) tambien; sin Colombia y con
	//--- "Si": la guerrilla de los pueblos (Resistencia) y los civiles; los ejercitos regulares no cambian
	VIOC_ES_INS = if (VIOC_ES_COLSIDE isEqualTo sideUnknown) then {if (_p == 1) then {[resistance]} else {[]}} else {[west, east, resistance] - [VIOC_ES_COLSIDE]};
	VIOC_ES_ON = _mod && {(_p == 1) || {(_p == 2) && {!(VIOC_ES_COLSIDE isEqualTo sideUnknown)}}};
	if (!VIOC_ES_ON) exitWith {diag_log format ["[VIOC voices_es] apagado (parametro %1, mod %2, Colombia %3)", _p, _mod, VIOC_ES_COLSIDE]};
	diag_log format ["[VIOC voices_es] activo: voz %1, Colombia en %2", VIOC_ES_VOICE, VIOC_ES_COLSIDE];
	while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
		call VIOC_ES_fnc_pass;
		sleep VIOC_ES_EVERY;
	};
};

class VIOC_VOICES_ES {
	title = "VIOC: Voces de radio en espanol (mod Spanish Voice-Overs; Auto = solo si Colombia esta en juego: ejercito colombiano, insurgencia, milicia, civiles y jugador; EE.UU. sigue en ingles)";
	values[] = {0,1,2};
	texts[] = {"No","Si (si el mod esta cargado)","Auto"};
	default = 2;
};
